#include <cmath>

struct Mat { float E[12]; };                       // E11..E43, rows of three
static void SetMultiply(Mat& r, const Mat& m1, const Mat& m2)
{
    for (int i = 0; i < 4; ++i)
        for (int j = 0; j < 3; ++j) {
            float s = m1.E[i * 3 + 0] * m2.E[0 * 3 + j] + m1.E[i * 3 + 1] * m2.E[1 * 3 + j] + m1.E[i * 3 + 2] * m2.E[2 * 3 + j];
